#!/usr/bin/env python3
"""Generate the compiler's HTML entity table from a local WHATWG entities.json."""

from argparse import ArgumentParser
from hashlib import sha256
import json
from pathlib import Path
import re


SOURCE = "https://html.spec.whatwg.org/entities.json"
TABLE = Path(__file__).resolve().parents[1] / "src/parser/html_entities.inc"


def table(source: bytes) -> str:
    data = json.loads(source)
    lines = [
        "// Generated by scripts/gen-html-entities.py from the WHATWG HTML standard.",
        f"// Source: {SOURCE}",
        f"// Source SHA-256: {sha256(source).hexdigest()}",
        "// Copyright © WHATWG (Apple, Google, Mozilla, Microsoft).",
        "// BSD-3-Clause. See third_party/whatwg-html/LICENSE.",
    ]
    for name, entry in sorted(data.items()):
        if not name.endswith(";"):
            continue
        if re.fullmatch(r"&[A-Za-z0-9]+;", name) is None:
            raise ValueError(f"invalid character reference name {name!r}")
        text = entry["characters"]
        if [ord(c) for c in text] != entry["codepoints"]:
            raise ValueError(f"character and code point forms differ for {name}")
        escaped = "".join(f"\\x{byte:02x}" for byte in text.encode("utf-8"))
        lines.append(f'    {{"{name[1:-1]}", "{escaped}"}},')
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = ArgumentParser(description=__doc__, epilog=f"Obtain entities.json from {SOURCE}")
    parser.add_argument("source", type=Path, help="a local copy of entities.json")
    parser.add_argument("--check", action="store_true", help="check the compiled table without writing it")
    args = parser.parse_args()
    contents = table(args.source.read_bytes())
    if args.check:
        if TABLE.read_text(encoding="utf-8") != contents:
            raise SystemExit(f"{TABLE} does not match {args.source}")
    else:
        TABLE.write_text(contents, encoding="utf-8")


if __name__ == "__main__":
    main()
